{"content":"import hashlib
import hmac
import json
import re

from payhook.errors import InvalidNotification

_TIMESTAMP_RE = re.compile(r"[0-9]+")
_CURRENCY_RE = re.compile(r"[A-Z]{3}")
_WINDOW_SECONDS = 300


def _parse_timestamp(headers):
    stamp = headers.get("X-Pay-Timestamp")
    if not isinstance(stamp, str) or not _TIMESTAMP_RE.fullmatch(stamp):
        raise InvalidNotification("missing or malformed X-Pay-Timestamp")
    return stamp, int(stamp)


def _parse_body(raw_body):
    try:
        raw_body = bytes(raw_body)
    except TypeError:
        raise InvalidNotification("notification body is not bytes") from None
    try:
        text = raw_body.decode("utf-8")
    except UnicodeDecodeError:
        raise InvalidNotification("notification body is not UTF-8") from None
    try:
        event = json.loads(text)
    except ValueError:
        raise InvalidNotification("notification body is not valid JSON") from None
    if not isinstance(event, dict):
        raise InvalidNotification("notification body is not a JSON object")
    return raw_body, event


def _normalize(event):
    event_id = event.get("event_id")
    account_id = event.get("account_id")
    amount_minor = event.get("amount_minor")
    currency = event.get("currency")
    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("missing or malformed event_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("missing or malformed account_id")
    if (not isinstance(amount_minor, int) or isinstance(amount_minor, bool)
            or amount_minor < 0):
        raise InvalidNotification("missing or malformed amount_minor")
    if not isinstance(currency, str) or not _CURRENCY_RE.fullmatch(currency):
        raise InvalidNotification("missing or malformed currency")
    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }


def _matches(presented, prefix, expected):
    if not isinstance(presented, str) or not presented.startswith(prefix):
        return False
    try:
        return hmac.compare_digest(presented[len(prefix):], expected)
    except TypeError:
        return False


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    if isinstance(secret, str):
        secret = secret.encode("utf-8")

    stamp, timestamp = _parse_timestamp(headers)
    if abs(now - timestamp) > _WINDOW_SECONDS:
        raise InvalidNotification("notification timestamp is outside the acceptance window")

    raw_body, event = _parse_body(raw_body)
    payment = _normalize(event)

    signed = stamp.encode("ascii") + b"."

    expected_v1 = hmac.new(secret, signed + raw_body, hashlib.sha256).hexdigest()
    if _matches(headers.get("X-Pay-Signature"), "v1=", expected_v1):
        return payment

    expected_r0 = hmac.new(
        secret, signed + payment["event_id"].encode("utf-8"), hashlib.sha256
    ).hexdigest()
    if _matches(headers.get("X-Pay-Receipt"), "r0=", expected_r0):
        return payment

    raise InvalidNotification("no valid v1 signature or r0 receipt")
